solution.Futures.java:
import java.util.*;
import java.util.concurrent.*;

public final class Futures {
    public static CompletableFuture<Integer> sumAll(List<CompletableFuture<Integer>> parts) {
        return CompletableFuture.allOf(parts.toArray(new CompletableFuture[0]))
                .thenApply(ignored -> parts.stream().mapToInt(CompletableFuture::join).sum());
    }

    public static <T> T valueNow(CompletableFuture<T> future, T fallback) {
        if (!future.isDone() || future.isCompletedExceptionally()) return fallback;
        return future.join();
    }
}

unitTests:
test("waits for every part without blocking", () -> {
    var a = new CompletableFuture<Integer>();
    var b = new CompletableFuture<Integer>();
    var sum = Futures.sumAll(List.of(a, b));
    check(!sum.isDone(), "not done while parts are unfinished");
    b.complete(2);
    check(!sum.isDone(), "still waiting for a");
    a.complete(40);
    checkEq(sum.join(), 42);
});

test("empty list", () -> {
    checkEq(Futures.sumAll(List.of()).join(), 0);
});

test("a failing part fails the sum", () -> {
    var ok = CompletableFuture.completedFuture(1);
    CompletableFuture<Integer> bad = CompletableFuture.failedFuture(new IllegalStateException("down"));
    var sum = Futures.sumAll(List.of(ok, bad));
    check(sum.isCompletedExceptionally());
    checkThrows(CompletionException.class, () -> sum.join());
});

test("valueNow", () -> {
    checkEq(Futures.valueNow(CompletableFuture.completedFuture("ready"), "later"), "ready");
    checkEq(Futures.valueNow(new CompletableFuture<String>(), "later"), "later");
    checkEq(Futures.valueNow(CompletableFuture.<String>failedFuture(new RuntimeException()), "later"), "later");
});

